parameters.jsCode:
const dish = $('When called by AI Agent').first().json.dish || 'unknown dish';
const raw = $json.content && $json.content[0] ? $json.content[0].text : '[]';

// Try to parse a JSON array out of the response
let ingredients = [];
try {
  const match = raw.match(/\[[\s\S]*\]/);
  if (match) {
    ingredients = JSON.parse(match[0]);
  }
} catch(e) {
  ingredients = [];
}

if (!Array.isArray(ingredients) || ingredients.length === 0) {
  return [{ json: { response: 'Could not extract ingredients for ' + dish + '. Ask the user what they want to make.' } }];
}

return [{
  json: {
    response: 'Ingredients for ' + dish + ': ' + JSON.stringify(ingredients) + '\n\nNow search Flipp for each of these items individually.'
  }
}];
